import React, { useRef } from 'react';

export interface ButtonProps {
  label: string;
  variant?: 'primary' | 'secondary' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  disabled?: boolean;
  loading?: boolean;
  icon_leading?: string;
  onPressed?: () => void;
  onLongPressed?: () => void;
}

const Button: React.FC<ButtonProps> = ({
  label,
  variant = 'primary',
  size = 'md',
  disabled = false,
  loading = false,
  icon_leading,
  onPressed,
  onLongPressed,
}) => {
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const longFiredRef = useRef<boolean>(false);

  const isInteractive = !disabled && !loading;

  const handlePointerDown = () => {
    if (!isInteractive) return;
    longFiredRef.current = false;
    timerRef.current = setTimeout(() => {
      longFiredRef.current = true;
      onLongPressed?.();
    }, 500);
  };

  const handlePointerUp = () => {
    if (timerRef.current) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
  };

  const handlePointerLeave = () => {
    if (timerRef.current) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
  };

  const handleClick = () => {
    if (!isInteractive) return;
    if (longFiredRef.current) {
      longFiredRef.current = false;
      return;
    }
    onPressed?.();
  };

  const baseStyle: React.CSSProperties = {
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: 8,
    cursor: isInteractive ? 'pointer' : 'not-allowed',
    opacity: disabled ? 0.5 : 1,
    padding: size === 'sm' ? '4px 8px' : size === 'lg' ? '12px 24px' : '8px 16px',
    fontSize: size === 'sm' ? 12 : size === 'lg' ? 18 : 14,
    borderRadius: 6,
    border: variant === 'ghost' ? '1px solid transparent' : '1px solid #ccc',
    background:
      variant === 'primary'
        ? '#2563eb'
        : variant === 'secondary'
        ? '#e5e7eb'
        : 'transparent',
    color: variant === 'primary' ? '#fff' : '#111',
    userSelect: 'none',
  };

  return (
    <div
      role="button"
      tabIndex={disabled ? -1 : 0}
      aria-disabled={disabled || loading}
      aria-busy={loading}
      data-variant={variant}
      data-size={size}
      data-loading={loading}
      style={baseStyle}
      onClick={handleClick}
      onMouseDown={handlePointerDown}
      onMouseUp={handlePointerUp}
      onMouseLeave={handlePointerLeave}
      onTouchStart={handlePointerDown}
      onTouchEnd={handlePointerUp}
      onKeyDown={(e) => {
        if ((e.key === 'Enter' || e.key === ' ') && isInteractive) {
          e.preventDefault();
          onPressed?.();
        }
      }}
    >
      {loading ? (
        <span aria-label="loading" role="status" data-testid="spinner">
          ⟳
        </span>
      ) : (
        <>
          {icon_leading && <span data-icon={icon_leading} aria-hidden="true">◆</span>}
          <span>{label}</span>
        </>
      )}
    </div>
  );
};

export default Button;
